 ('policy', ['Obtain explicit owner selection of optional specialties and provider connectors; all eight named tasks remain stored without implying that every connector will be implemented.', 'For selected specialties, obtain clinician-led versioned fields/workflows and review boundaries; no universal template or specialty competence is assumed.', 'Record chosen scope, deferred tasks, qualified reviewers and acceptance fixtures without renumbering stable task IDs or cancelling history.'], ['Review two distinct specialty needs and identify unsupported workflows explicitly.', 'No selected specialty/provider or no qualified reviewer keeps optional implementation blocked.']),
 ('policy', ['Verify actual medication catalogue/national prescription source, licensing, redistribution, version/update and access terms using provider evidence.', 'Record whether an EDA/national interface exists and is accessible to this entity; unavailable access yields a feasibility finding, never a fabricated adapter.', 'Specify approved fallback/manual-entry behavior and preserve M2 clinician review/signing authority; no automatic substitution or dosing recommendation.'], ['Missing license, revoked access, stale catalogue and unsupported medicine identity fail closed.', 'Compare provider evidence with claimed API/version and reject unsupported national-integration marketing.']),
 ('provider', ['Select one verified lab partner with documented protocol/version, sandbox access, commercial/data terms and explicit identity-matching rules.', 'Map request/result IDs and provenance to the exact patient relationship/order; ambiguous matches are quarantined for authorized review, never merged by contact.', 'Implement authenticated idempotent delivery/retry/reconciliation with result review/release still clinician-controlled.'], ['Replay duplicate result, send an amended result out of order and preserve source/version history.', 'Unknown patient/order or failed signature is quarantined without releasing content or marking clinical review.']),
 ('provider', ['Approve one imaging workflow and partner exchange contract including identifiers, document/image access, version and minimum-necessary disclosure.', 'Preserve order/patient/doctor provenance, private viewer/document authorization and reconciliation of external status.', 'Do not assume a particular imaging standard, endpoint or diagnostic interpretation before verified partner requirements.'], ['Expired external access, wrong-patient study and partner outage remain safe and recoverable.', 'Replaced/amended report retains history and requires the approved clinical review before patient release.']),
 ('provider', ['Approve partner/contract, fulfillment fields and permitted prescription release with patient/doctor consent and minimum data.', 'Exchange only authorized signed/current prescription versions and fulfillment/status events with idempotency and provenance.', 'Stopping/amending a prescription reconciles partner state; neither adapter nor pharmacy-status UI may infer medication substitution or prescribing/dispensing authority.'], ['Duplicate fulfillment receipt and delayed old-version status do not revive a stopped prescription.', 'Reject unapproved recipient, revoked consent and unsigned prescription transmission.']),
 ('policy-provider', ['Obtain current qualified applicability and contracting review for the named insurer/UHIA route, actual API availability, standards/version and credential eligibility.', 'Define approved eligibility/claim fields, consent, coding responsibilities and financial reconciliation without fabricating coverage or reimbursement.', 'Build the first connector only after verified contract/sandbox evidence; unavailable access is a documented feasibility blocker, not a mock production integration.'], ['Missing enrollment, unknown policy, disputed claim and denied eligibility produce explicit unresolved states.', 'Duplicate claim/reversal and partner timeout reconcile without inventing payment or altering clinical documentation.']),
 ('provider', ['Select the actual standard/profile/version and partner contract through explicit decision, with approved minimum clinical dataset and patient/doctor release policy.', 'Map stable identifiers, units, terminology, timestamps, provenance and amendment references; unsupported fields must be reported rather than silently dropped.', 'Validate authorized export/import against partner fixtures with idempotency and quarantine ambiguous identity/version matches; cross-doctor access remains independently granted.'], ['Round-trip approved synthetic records with amendments and verify field/provenance fidelity.', 'Reject unsupported profile, mismatched identity, missing required field and revoked sharing authorization.']),
 ('review', ['Verify each explicitly selected optional module independently using partner sandbox/contract and qualified specialty review on the exact candidate.', 'Retain deferred/unavailable module IDs and list exclusions; do not claim telemedicine, AI diagnosis, hospital systems or universal provider coverage.', 'Obtain separate rollout authorization per module with incident/recovery and compatibility evidence; this task does not deploy or purchase access.'], ['Disable one optional connector during partner outage without weakening core clinical access or corrupting pending messages.', 'Incomplete partner terms, failed identity reconciliation or absent clinical approval blocks that module while preserving unrelated accepted evidence.']),
