def build_later(number, source, finish, root, shared):
 milestone=source['milestones'][number-1]; mid=milestone['milestone_id']; rows=DETAILS[number]
 assert len(rows)==milestone['task_count']
 decisions=[{'decision_id':mid+'-GATE-START','title':mid+' parent-controlled start gate','status':'open','decision_text':'Remain OPEN until all nine milestones are safely stored and parent verifies dependency acceptance, exact live runtime/registration/commands/paths and authorizes this milestone. Import does not grant execution.','source':'Current delegated instruction.'}]
 for suffix,title,producer in GATES[number]:
  decisions.append({'decision_id':mid+'-GATE-'+suffix,'title':title,'status':'open','decision_text':f'Evidence from {producer} must identify the accountable reviewer, approved scope/version and constraints. Missing evidence stays OPEN. A worker cannot approve this on behalf of a reviewer.','source':producer,'producer_task_id':producer})
 requirements=[{'requirement_id':mid+'-R001','title':'Milestone boundary and invariant','summary':milestone['title']+'. Synthetic-only implementation; retain doctor ownership, independent secretary grants and separate patient identity/relationship/encounter; no clinical/legal/provider/commercial authority inferred.','status':'proposed','provenance':'Supplied roadmap v0.2 plus current delegated scope.'}]
 tasks=[]
 for index,(src,row) in enumerate(zip(milestone['tasks'],rows),1):
  kind,criteria,scenarios=row; tid=src['task_id']; key=tid.lower(); fid=mid+f'-F{index:03d}'
  req={'requirement_id':fid,'title':src['title'],'summary':src['objective']+' Acceptance: '+' '.join(criteria),'status':'proposed','provenance':'Detailed decomposition of '+tid+' from supplied roadmap; ordinary design choices, evidence-gated domain decisions.'};requirements.append(req)
  paths=[root, 'release-fragments/']; outputs=[root+f'implementation/{key}.md']; plan=[{'version':2,'kind':'command','description':'Check diff hygiene','command':'git diff --check'},{'version':2,'kind':'command','description':'Check pinned workspace architecture and boundaries','command':'pnpm check'}]
  policy=kind=='policy'; mobile=number in (4,5) and not policy
  if not policy:
   paths += ['apps/doctor-suit/app/','apps/doctor-suit/server/','apps/doctor-suit/tests/','apps/doctor-suit/i18n/']+shared
   unit=f'apps/doctor-suit/tests/unit/{key}.test.mjs';outputs.append(unit)
   plan.append({'version':2,'kind':'planned_test','description':'Execute task-specific state, protocol and failure assertions','expected_outputs':[unit],'commands':[key+'-unit']})
   plan.append({'version':2,'kind':'command','description':'Run full repository unit regression for affected consumers','command':'pnpm test'})
   if kind in ['data','policy-data','review-data','provider','policy-provider','review']:
    paths += ['apps/doctor-suit/supabase/'];sql=f'apps/doctor-suit/supabase/tests/{key}.sql';outputs.append(sql)
    plan.append({'version':2,'kind':'planned_test','description':'Verify database authorization, replay and write integrity with disposable fixtures','expected_outputs':[sql],'commands':[key+'-data'],'requires':['database','rls-authorization']})
   if not mobile and kind!='unit':
    browser=f'apps/doctor-suit/tests/e2e/{key}.spec.ts';outputs.append(browser)
    plan.append({'version':2,'kind':'planned_test','description':'Verify browser journey, denial and recovery states','expected_outputs':[browser],'commands':[key+'-browser'],'requires':['browser']})
   if mobile:
    surface='doctor' if number==4 else 'patient';paths += [f'apps/doctor-suit/mobile/{surface}/']
    outputs += [root+f'implementation/{key}-device-evidence.json']
    plan.append({'version':2,'kind':'external_gate','description':'Exact-candidate device and chosen-platform build/test evidence; Node protocol tests alone cannot satisfy mobile acceptance','blocker':'approved_platform_command_mapping_and_device_receipts_required','phase':'pre_publication'})
    criteria += ['Use only the explicitly approved platform/renderer and registered build/device test commands. The reserved mobile path grants no framework choice; re-review the packet and registration after the platform decision, before native implementation.']
  if policy or kind in ['provider','policy-provider','review','policy-data','review-data']:
   plan.append({'version':2,'kind':'external_gate','description':'Independent accountable human reviewer evidence for the task acceptance and unresolved domain decisions','blocker':'reviewer_identity_scope_candidate_and_decision_evidence_required','phase':'pre_publication'})
  if index==milestone['task_count']:
   for cmd in ['pnpm typecheck','pnpm lint','pnpm build']:plan.append({'version':2,'kind':'command','description':'Run milestone candidate '+cmd,'command':cmd})
   plan.append({'version':2,'kind':'external_gate','description':'Independent exact-candidate affected shared-consumer acceptance evidence','blocker':'shared_consumer_regression_receipts_required','phase':'pre_publication'})
  deps=list(src['task_dependencies'])
  if index==1:
   for prereq in milestone['depends_on']:
    m=next(m for m in source['milestones'] if m['milestone_id']==prereq);deps.append(m['tasks'][-1]['task_id'])
  # Preserve the source chain and strengthen the exit gate to all named tasks.
  if index==milestone['task_count']:deps += [t['task_id'] for t in tasks]
  blocked=[mid+'-GATE-START']
  for suffix,_,producer in GATES[number]:
   if int(producer[-3:])<index and suffix!='RELEASE':blocked.append(mid+'-GATE-'+suffix)
  if number==4 and index in [6,7]:deps += ['DOS-M2-014']
  if number==5 and index>=4:deps += ['DOS-M2-012']
  if number==5 and index>=6:deps += ['DOS-M2-007','DOS-M2-008']
  if number==5 and index==2:deps += ['DOS-M4-001']
  if number==8 and index==3:deps += ['DOS-M6-009']
  if number==7 and index==10:blocked.append('DOS-M1-D005')
  producers=[d['decision_id'] for d in decisions if d.get('producer_task_id')==tid]
  if producers:
   criteria += ['Prepare evidence for '+', '.join(producers)+'. Stop before any provider/native/live-data dependent implementation until the accountable reviewer approves the relevant decision; producing this packet does not grant approval.']
  req['summary']=src['objective']+' Acceptance: '+' '.join(criteria)
  tasks.append({'task_id':tid,'milestone_id':mid,'sequence':number*1000+index*10,'priority':100 if number<9 else 200,'title':src['title'],'objective':src['objective'],'task_type':'research' if policy else 'review' if kind in ['review','review-data'] else 'feature','risk_level':'critical' if number in [2,5,7] else 'high','acceptance_criteria':criteria,'verification_scenarios':scenarios,'verification_plan':plan,'allowed_paths':paths,'expected_outputs':outputs,'linked_requirement_ids':[mid+'-R001',fid],'task_dependencies':sorted(set(deps)),'blocking_decision_ids':blocked,'produces_decision_ids':producers,'specific_evidence':[f'Create {outputs[0]} with the task decisions, API/state contract, scenarios and evidence references; text alone is not a passing product test.','Retain the supplied roadmap objective and stable ID; record new decisions without replacing historical execution states.']})
 finish(milestone,tasks,requirements,decisions)
